import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const container = new THREE.Group();

  // Load texture from asset URL
  const imageUrl = config.assets?.imageUrl || '/prism-mock/home/nodes/cta-hero-isolated.png';
  const textureMap = ctx.textureLoader.load(imageUrl);
  textureMap.colorSpace = THREE.SRGBColorSpace;

  // Create plane geometry with aspect ratio from atlas region (512x320)
  const atlasAspect = 512 / 320;
  const baseWidth = 1.6;
  const baseHeight = baseWidth / atlasAspect;

  const geometry = new THREE.PlaneGeometry(baseWidth, baseHeight);

  // Material: MeshBasicNodeMaterial with texture (no lighting for static composition)
  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = texture(textureMap);

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply transform from config
  const position = config.scenePosition || [-3.2, -0.3, 0];
  const rotation = config.sceneRotation || [0, 0, 0];
  const scale = config.sceneScale || [1, 1, 1];

  mesh.position.fromArray(position);
  mesh.rotation.fromArray(rotation);
  mesh.scale.fromArray(scale);

  container.add(mesh);

  // Cleanup resources
  container.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    textureMap.dispose();
  };

  // Handler registry (static card, no interactions)
  container.userData.handlers = {};

  return container;
}
